sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    try {
        var positionSummary = new GlideRecord("x_hsb11_mss_pos_custody_positions_summary");
        if (current.response_code_for_summary == "200") {
            var responsebody = current.response_body_for_summary.toString();
            var respBody = JSON.parse(responsebody);
            for (var i = 0; i < respBody.data.length; i++) {
                positionSummary.initialize();
                positionSummary.security_account = respBody.data[i].safekeepingAccountIdentification;
                positionSummary.account_name = respBody.data[i].safekeepingAccountName;
                positionSummary.security_id = respBody.data[i].financialInstrumentIdentification.hsbcIdentifier;
                positionSummary.isin = respBody.data[i].financialInstrumentIdentification.isin;
				positionSummary.security_name = respBody.data[i].financialInstrumentIdentification.description;
                positionSummary.available_balance = respBody.data[i].balances.available.quantity;
                positionSummary.traded_balance = respBody.data[i].balances.traded.quantity;
                positionSummary.settled_balance = respBody.data[i].balances.settled.quantity;
                positionSummary.trade_id = current.trade_reference;
                positionSummary.type = current.type;
                positionSummary.triggered_by = current.triggered_by;
				positionSummary.security_currency = respBody.data[i].financialInstrumentIdentification.currency;//MSSCUSTODY-8179
				positionSummary.market_value_in_security_currency = respBody.data[i].balances.settled.marketValueInSecurityCurrency;//MSSCUSTODY-8179
				positionSummary.market_value_in_usd = respBody.data[i].balances.settled.marketValueInReportCurrency;//MSSCUSTODY-8179

                if (current.parent_position_ondemand != '')
                    positionSummary.position_summary_ondemand = current.parent_position_ondemand;
                else
                    positionSummary.position_summary_ondemand = current.sys_id;
                positionSummary.insert();
            }
        }
    } catch (e) {
        gs.info("unexpected error occured" + e);
    }
})(current, previous);
